def convert_args(self, request: Request, user_id, *args, **kwargs):
    if user_id == "me":
        if not request.user.is_authenticated:
            raise ResourceDoesNotExist
        user_id = request.user.id

    try:
        user = User.objects.get(id=user_id)
    except (User.DoesNotExist, ValueError):
        raise ResourceDoesNotExist

    self.check_object_permissions(request, user)

    kwargs["user"] = user
    return args, kwargs

class UserPermission(SentryPermission):
    def has_object_permission(self, request: Request, view, user: User | RpcUser | None = None):
        if user is None:
            user = request.user
        if request.user.id == user.id:
            return True
        if is_system_auth(request.auth):
            return True
        if request.auth:
            return False
        if is_active_superuser(request):
            return True
        return False

def delete(self, request: Request, user: User, notification_option_id: str) -> Response:
    try:
        option = NotificationSettingOption.objects.get(
            id=notification_option_id,
        )
    except NotificationSettingOption.DoesNotExist:
        return Response(status=status.HTTP_404_NOT_FOUND)

    option.delete()
    return Response(status=status.HTTP_204_NO_CONTENT)

def put(self, request: Request, user: User) -> Response:
    serializer = UserNotificationSettingsProvidersDetailsSerializer(data=request.data)
    if not serializer.is_valid():
        return self.respond(serializer.errors, status=400)

    data = serializer.validated_data
    new_rows = []
    with transaction.atomic(router.db_for_write(NotificationSettingProvider)):
        for provider in allowed_providers:
            value = (
                NotificationSettingsOptionEnum.ALWAYS.value
                if provider in data["provider"]
                else NotificationSettingsOptionEnum.NEVER.value
            )
            (
                notification_setting_provider,
                created,
            ) = NotificationSettingProvider.objects.update_or_create(
                user_id=user.id,
                scope_type=data["scope_type"],
                scope_identifier=data["scope_identifier"],
                type=data["type"],
                provider=provider,
                defaults={"value": value},
            )
            new_rows.append(notification_setting_provider)
    return Response(
        serialize(new_rows, request.user, NotificationSettingsProviderSerializer()),
        status=status.HTTP_201_CREATED,
    )

